import { createContext } from "react";
import React from "react";

/*
Creates context for the toggles on the stat buttons
*/

interface Toggle {
    isToggled : boolean;
    setToggled : (toggle : boolean) => void;
};

interface ToggleMap {
    toggleMap : Record<string, Toggle>;
    updateMap : (key : string) => void
}

export const Toggles = React.createContext<ToggleMap>({toggleMap: {}, updateMap: (key : string) => {}});

